import { ArrowLeft } from 'lucide-react'
import { ReactNode } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { LEGAL_DATE, MAIL_PROVIDER, NEW_TERMS_DATE, OPERATOR, SITE } from '../legal'
import { SELLER, SHOW_SELLER_ID } from '../seller'

/**
 * Юридические документы сайта. Тексты — рабочий шаблон под то, что приложение реально делает;
 * перед запуском платных функций их стоит показать юристу.
 */

function Doc({ title, date = LEGAL_DATE, children }: { title: string; date?: string; children: ReactNode }) {
  const nav = useNavigate()
  return (
    <div className="legal-wrap">
      <article className="legal card stack">
        <button className="btn ghost sm" style={{ alignSelf: 'flex-start' }} onClick={() => (history.length > 1 ? nav(-1) : nav('/'))}>
          <ArrowLeft size={16} />Назад
        </button>
        <h1>{title}</h1>
        <p className="muted small">Редакция от {date}</p>
        {children}
        <LegalLinks />
      </article>
    </div>
  )
}

/** Ссылки на все документы — внизу форм входа, регистрации и в разделе «Семья». */
export function LegalLinks() {
  return (
    <nav className="legal-links small" aria-label="Документы">
      <Link to="/privacy">Политика обработки персональных данных</Link>
      <Link to="/consent">Согласие на обработку данных</Link>
      <Link to="/terms">Пользовательское соглашение</Link>
    </nav>
  )
}

const DATA_LIST = (
  <ul>
    <li>идентификационные и контактные данные: имя (псевдоним), указанное Пользователем, адрес электронной почты;</li>
    <li>учётные данные: пароль в виде необратимой хеш-функции (bcrypt), дата регистрации, дата и редакция данного согласия;</li>
    <li>сведения о домашней аптечке семьи: наименования лекарственных препаратов, форма выпуска, дозировка, действующее вещество, производитель, показания («от чего помогает»), противопоказания, заметки, сроки годности, даты вскрытия, остатки, место хранения, коды маркировки с упаковки (GTIN, серия, серийный номер), фотографии упаковок;</li>
    <li>сведения о приёме лекарственных препаратов (история приёма), личные отметки «избранное» и «помогает мне», личные заметки;</li>
    <li>история болезней: даты болезни, название и комментарий, которые Пользователь вносит сам, и фотографии документов, которые он прикрепляет (справки, выписки, назначения врача, результаты анализов); такие записи личные и видны только самому Пользователю;</li>
    <li>личное расписание приёма лекарственных препаратов (наименование, доза, дни недели и время приёма, срок курса), настройки уведомлений о приёме и журнал отправленных уведомлений (какой приём и когда);</li>
    <li>технические данные: IP-адрес, дата и время запросов, сведения о браузере в журналах веб-сервера.</li>
  </ul>
)

export function Privacy() {
  return (
    <Doc title="Политика в отношении обработки персональных данных" date="3 октября 2026 г.">
      <h2>1. Общие положения</h2>
      <p>1.1. Настоящая Политика в отношении обработки персональных данных (далее — «Политика») разработана во исполнение ч. 2 ст. 18.1 Федерального закона от 27.07.2006 № 152-ФЗ «О персональных данных» (далее — «Закон») и определяет порядок и условия обработки персональных данных пользователей сервиса «Капсулка», размещённого в сети «Интернет» по адресу {SITE} (далее — «Сервис»), а также меры по обеспечению их безопасности.</p>
      <p>1.2. Оператором персональных данных является физическое лицо {OPERATOR.name} (далее — «Оператор»). Адрес электронной почты для обращений субъектов персональных данных: {OPERATOR.email}. Оператор уведомил Роскомнадзор о намерении обрабатывать персональные данные: уведомление внесено в реестр операторов, номер уведомления {OPERATOR.rknNotice}.</p>
      <p>1.3. Политика является общедоступным документом и опубликована в Сервисе в соответствии с ч. 2 ст. 18.1 Закона. Термины используются в значении, определённом ст. 3 Закона.</p>

      <h2>2. Цели обработки</h2>
      <p>2.1. Оператор обрабатывает персональные данные исключительно в следующих целях: (а) регистрация и идентификация Пользователя, предоставление доступа к Сервису; (б) ведение общей домашней аптечки семьи: учёт лекарственных препаратов, сроков годности, остатков и истории приёма, поиск по сведениям, внесённым самим Пользователем, формирование по запросу Пользователя выписок и напоминаний; ведение личного расписания приёма и направление Пользователю напоминаний о приёме, а по его желанию — уведомление указанного им доверенного лица (п. 5.8); (в) рассмотрение обращений и запросов Пользователей, направление Пользователю служебных писем (подтверждение адреса электронной почты, восстановление доступа, уведомления об изменении документов); (г) обеспечение безопасности Сервиса и предотвращение несанкционированного доступа; (д) приём оплаты платных функций (тариф «Капсулка Плюс»), оформление чеков, рассмотрение вопросов об оплате и возвратах.</p>
      <p>2.2. Персональные данные не используются для рекламы, продвижения товаров, профилирования и принятия решений, порождающих юридические последствия, исключительно на основании автоматизированной обработки (ст. 16 Закона), не продаются и не передаются аптекам, рекламодателям и иным третьим лицам, за исключением уведомления доверенного лица, которое Пользователь сам поручил направлять (п. 5.8).</p>

      <h2>3. Состав обрабатываемых персональных данных и категории субъектов</h2>
      <p>3.1. Субъекты: (а) зарегистрированные Пользователи Сервиса; (б) доверенные лица — физические лица, имя и адрес электронной почты которых указал Пользователь для получения уведомлений (п. 5.8). Данные Пользователей:</p>
      {DATA_LIST}
      <p>Данные доверенных лиц: имя и адрес электронной почты, статус (ожидает ответа, согласился, отказался, отписался), дата и редакция данного ими согласия.</p>
      <p>При оплате тарифа «Капсулка Плюс» дополнительно обрабатываются: идентификатор платежа, сумма, дата, оплаченный срок, адрес электронной почты для направления чека, а при включённом автопродлении — идентификатор сохранённого способа оплаты, выданный платёжным сервисом. Реквизиты банковской карты Оператору не передаются и им не хранятся.</p>
      <p>3.2. Сведения о лекарственных препаратах, истории приёма, истории болезней (в том числе прикреплённых фотографиях документов) и расписании приёма и отметки «помогает мне» могут прямо или косвенно указывать на состояние здоровья, в связи с чем Оператор относит их к специальной категории персональных данных (ч. 1 ст. 10 Закона) и обрабатывает их только при наличии согласия Пользователя в письменной форме (п. 1 ч. 2 ст. 10 Закона), выраженного в электронной форме в порядке, установленном Сервисом.</p>
      <p>3.3. Пользователь обязуется не вносить в Сервис персональные данные третьих лиц (в том числе сведения о здоровье родственников) без их согласия либо без полномочий законного представителя; это относится и к имени и адресу электронной почты доверенного лица, которого Пользователь обязан заранее поставить в известность. Биометрические персональные данные не обрабатываются.</p>

      <h2>4. Правовые основания обработки</h2>
      <p>Согласие субъекта на обработку персональных данных (п. 1 ч. 1 ст. 6, п. 1 ч. 2 ст. 10 Закона), оформленное отдельным документом в соответствии с ч. 1 ст. 9 Закона; исполнение Пользовательского соглашения и Публичной оферты «Капсулка Плюс», стороной которых является субъект (п. 5 ч. 1 ст. 6 Закона) — в части данных учётной записи и данных об оплате; осуществление законных интересов Пользователя и Оператора (п. 7 ч. 1 ст. 6 Закона) — в части направления приглашения доверенному лицу (п. 5.8).</p>

      <h2>5. Порядок и условия обработки</h2>
      <p>5.1. Обработка осуществляется с использованием средств автоматизации и включает сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, предоставление (доступ) участникам семьи в Сервисе, блокирование, удаление и уничтожение.</p>
      <p>5.2. Доступ к данным: участники семьи, в которую вступил Пользователь, видят общую аптечку, имя и адрес электронной почты Пользователя, его отметки «помогает мне» и историю приёма (без личных комментариев к приёму) и могут выгрузить её в файл; личное расписание приёма, настройки уведомлений, история болезней и фотографии документов видны только самому Пользователю (членам семьи и доверенному лицу они не показываются и не передаются); Оператор как администратор Сервиса видит перечень учётных записей и семей. Фотографии упаковок доступны по случайной ссылке, которую невозможно подобрать; Пользователю не следует загружать фотографии, на которых видны его фамилия или иные сведения о нём.</p>
      <p>5.3. Вычислительные мощности для размещения Сервиса предоставляет хостинг-провайдер на территории Российской Федерации; Оператор не поручает ему обработку персональных данных и не предоставляет ему доступ к содержимому базы данных.</p>
      <p>5.4. Для отправки служебных писем (в том числе письма с кодом восстановления пароля) и напоминаний (п. 5.7 и 5.8) Оператор поручает обработку адреса электронной почты и имени Пользователя, адреса и имени доверенного лица, а также содержания писем (наименования лекарственных препаратов, дозы, время приёма, сроки годности, остатки) (ч. 3 ст. 6 Закона) почтовому сервису {MAIL_PROVIDER}, серверы которого находятся на территории Российской Федерации. Такое лицо обрабатывает данные только для доставки писем и обязано соблюдать конфиденциальность и меры защиты, предусмотренные ст. 19 Закона. Рекламные рассылки не осуществляются.</p>
      <p>5.5. При поиске наименования по штрихкоду Сервис направляет во внешние справочники (поисковую систему, Open Food Facts) исключительно цифровой код товара без каких-либо сведений о Пользователе; такой код персональными данными не является. Сведения, которые Пользователь вносит или исправляет по штрихкоду, видны только в аптечках его семьи; общий справочник Сервиса пополняется только из внешних открытых источников.</p>
      <p>5.6. Запись, систематизация, накопление, хранение, уточнение и извлечение персональных данных граждан Российской Федерации осуществляются с использованием баз данных, находящихся на территории Российской Федерации (ч. 5 ст. 18 Закона). Трансграничная передача персональных данных не осуществляется, за исключением случая, указанного в п. 5.7, при наличии отдельного согласия Пользователя.</p>
      <p>5.7. Напоминания. По выбору Пользователя Сервис один раз в день направляет ему список лекарственных препаратов с истекающим или истёкшим сроком годности либо остатком, достигшим заданного Пользователем порога (наименования, сроки годности, остатки, а при нескольких аптечках — их названия): на адрес электронной почты — через почтовый сервис, указанный в п. 5.4, и (или) в мессенджер Telegram. Для Telegram Оператор хранит идентификатор чата и имя пользователя Telegram; сообщения передаются компании Telegram, находящейся за пределами Российской Федерации, что является трансграничной передачей персональных данных и осуществляется только после того, как Пользователь сам подключил бота и дал отдельное <Link to="/consent-telegram">согласие</Link>, и после направления Оператором уведомления в Роскомнадзор (ч. 3 ст. 12 Закона). Пользователь может в любой момент приостановить отправку, сняв соответствующую отметку в разделе «Семья» → «Напоминания», либо отключить Telegram кнопкой «Отключить» или командой /stop в боте; при отключении Telegram идентификатор чата и имя пользователя Telegram удаляются.</p>
      <p>5.8. Расписание приёма и уведомления по расписанию.</p>
      <p>(а) Расписание. Пользователь может вести личное расписание приёма лекарственных препаратов (п. 3.1); добавление новых назначений доступно при тарифе «Плюс» (п. 6.2 Соглашения), ранее созданные остаются доступными. Оно видно только Пользователю и не показывается участникам семьи. Отметка «Принял(а)» записывается в историю приёма и видна участникам семьи в порядке п. 5.2. Назначения по аптечке удаляются при выходе Пользователя из неё, все назначения — при удалении учётной записи.</p>
      <p>(б) Уведомления Пользователю. Если у семьи Пользователя действует тариф «Плюс» (п. 6.8 Соглашения) и Пользователь включил соответствующую настройку, Сервис направляет на адрес электронной почты учётной записи письмо за выбранное Пользователем время до приёма и повторное письмо, если после приёма в истории приёма нет отметки. В письмах указываются наименование лекарственного препарата, доза и время приёма. Письма отправляются через почтовый сервис, указанный в п. 5.4; Telegram для них не используется. Электронная почта не является защищённым каналом связи: доступ к почтовому ящику Пользователя обеспечивает сам Пользователь. Уведомления можно отключить на вкладке «Расписание».</p>
      <p>(в) Доверенное лицо. Пользователь при действии тарифа «Плюс» (п. 6.8 Соглашения) вправе указать доверенное лицо — человека, которому Сервис сообщит, что плановый приём не отмечен. Оператор получает от Пользователя имя и адрес электронной почты этого лица и направляет ему приглашение: письмо, в котором сообщается, кто его указал, для чего и как согласиться, отказаться или отписаться. Приглашение направляется на основании п. 7 ч. 1 ст. 6 Закона (осуществление законных интересов Пользователя и Оператора по получению согласия этого лица при условии, что права и свободы доверенного лица не нарушаются); не более двух приглашений на один адрес электронной почты в сутки. Сведения, предусмотренные ч. 3 ст. 18 Закона, доводятся до доверенного лица приглашением и страницей <Link to="/consent-trusted">согласия доверенного лица</Link>. До его согласия иные уведомления ему не направляются; если он не ответил, приглашение остаётся без последствий. Уведомления начинаются только после согласия, которое доверенное лицо даёт само, нажав кнопку на странице по ссылке из приглашения (дата и редакция согласия фиксируются). Если Пользователь включил функцию «Сообщать ему» и после повторного напоминания приём не отмечен, доверенному лицу направляется письмо о том, что плановый приём не отмечен, с указанием времени приёма; наименование лекарственного препарата в письме указывается только если Пользователь отдельно включил эту опцию. Не более 12 писем доверенному лицу в сутки. Такое письмо раскрывает доверенному лицу сведения о состоянии здоровья Пользователя (факт назначенного приёма), поэтому направляется только по поручению Пользователя, выраженному в отдельном <Link to="/consent-share">согласии на передачу сведений доверенному лицу</Link>, которое даётся отметкой при включении этой функции (дата и редакция согласия сохраняются; без него письма доверенному не отправляются). В каждом письме есть ссылка «Отписаться»; доверенное лицо может отказаться сразу по приглашению.</p>
      <p>(г) Сроки. Имя и адрес электронной почты доверенного лица, не ответившего на приглашение, удаляются через 30 дней после его отправки. После согласия они хранятся, пока доверенное лицо не отпишется, Пользователь не нажмёт «Убрать и удалить почту» или не удалит учётную запись, либо до удовлетворения запроса этого лица об удалении (п. 9.3). При отказе или отписке доверенного лица отправка писем прекращается, а его имя и адрес удаляются немедленно (остаётся только статус). Журнал отправленных уведомлений (какой приём и когда) служит только для того, чтобы не отправлять письмо повторно, и хранится до удаления учётной записи.</p>
      <p>(д) Почтовые ящики. Письма доставляются на адреса, которые указали Пользователь и доверенное лицо; Оператор не выбирает почтовый ящик получателя. Если ящик размещён у провайдера за пределами Российской Федерации, Оператор исходит из того, что доставка осуществляется по адресу, указанному самим получателем, и не является поручением обработки данных этому провайдеру.</p>
      <p>5.9. Оплата. Платежи за тариф «Капсулка Плюс» принимает платёжный сервис ЮKassa. Для проведения платежа ему передаются сумма, назначение платежа, идентификатор платежа, номер семьи, номер учётной записи плательщика и адрес электронной почты Пользователя; платёжные реквизиты вводятся на стороне платёжного сервиса, который обрабатывает их по своим правилам и своей политике обработки персональных данных. Оператор получает от него сведения о статусе платежа, идентификатор платежа и, при включённом автопродлении, идентификатор сохранённого способа оплаты, но не получает реквизиты банковской карты. Чек формируется Оператором и направляется на адрес электронной почты Пользователя. Автопродление включается только по отдельному согласию Пользователя; его можно отключить в любой момент в Сервисе, после чего идентификатор способа оплаты для новых списаний не используется.</p>
      <p>5.10. Перенос данных между семьями. Если после окончания тарифа «Капсулка Плюс» человек переводится из общей семьи в личную семью, Оператор переносит вместе с ним его отметки приёма, расписание, избранное и одну аптечку со всеми лекарствами в ней; лекарства, внесённые им в другие аптечки прежней семьи, остаются в этих аптечках. Перенос происходит внутри Сервиса, третьим лицам данные не передаются, состав данных не меняется.</p>

      <h2>6. Сроки обработки и уничтожение</h2>
      <p>6.1. Персональные данные обрабатываются до достижения целей обработки, то есть до удаления учётной записи, либо до отзыва согласия.</p>
      <p>6.2. При удалении учётной записи или отзыве согласия данные Пользователя, включая расписание приёма, историю болезней и фотографии документов, настройки и журнал уведомлений и данные доверенного лица, удаляются из рабочей базы данных немедленно; из резервных копий, хранящихся не более 14 дней, — по истечении срока их хранения, но в любом случае не позднее 30 дней (ч. 4 и 5 ст. 21 Закона). Общие записи аптечки, внесённые Пользователем, остаются у других участников семьи без указания на Пользователя; если Пользователь был последним участником, семья удаляется целиком. Технические журналы веб-сервера хранятся не более 30 дней.</p>
      <p>6.3. Сведения об оплатах (идентификатор платежа, сумма, дата, оплаченный срок) хранятся в течение срока, необходимого для учёта, рассмотрения обращений и защиты от возможных споров, но не более трёх лет с даты платежа (ст. 196 Гражданского кодекса Российской Федерации), и при удалении учётной записи обезличиваются, если иное не требуется законом. Идентификатор способа оплаты удаляется при отключении автопродления или удалении учётной записи.</p>
      <p>6.4. Служебные сведения о приглашениях в семью (код, срок его действия, номера людей: выпустившего код и воспользовавшегося им) хранятся до истечения срока действия кода и удаляются в течение 30 дней после этого. Журнал изменений семьи (вступление, выход, исключение, предложение передать владение, согласие и отказ, передача владения, создание и удаление аптечек, выдача тарифа администратором: вид события, дата, номера людей и номер аптечки) хранится 12 месяцев либо до удаления семьи; имена людей и названия аптечек в нём не хранятся. Сведения о предложениях передать владение семьёй (кто предложил, кому, итог; номера людей) хранятся 30 дней после окончания срока ответа. При удалении учётной записи номер человека в этих записях обнуляется.</p>
      <p>6.5. Учётная запись, адрес электронной почты которой не подтверждён в течение семи дней после регистрации, и связанные с ней данные удаляются автоматически (учётные записи администраторов Сервиса не удаляются). Код для восстановления пароля (восемь цифр) действует тридцать минут и после ввода подтверждает адрес электронной почты; на один адрес направляется не более трёх писем с таким кодом в час и не более шести в сутки; повторная отправка кода подтверждения адреса при регистрации ограничена десятью письмами в сутки.</p>

      <h2>7. Меры по обеспечению безопасности</h2>
      <p>Оператор принимает правовые, организационные и технические меры, предусмотренные ст. 18.1 и 19 Закона: шифрование соединения (HTTPS, HSTS), хранение паролей только в виде хеша, требования к сложности пароля, ограничение числа попыток входа и писем с кодом восстановления, возможность сменить пароль и завершить сеансы на всех устройствах, разграничение доступа к данным семьи, ограничение административного доступа к серверу, резервное копирование. В случае выявления неправомерной или случайной передачи (предоставления, распространения) персональных данных Оператор уведомляет Роскомнадзор в течение 24 часов и о результатах внутреннего расследования — в течение 72 часов (ч. 3.1 ст. 21 Закона), а также информирует затронутых Пользователей.</p>

      <h2>8. Файлы cookie и хранилище браузера</h2>
      <p>Сервис не использует рекламные и аналитические cookie и сторонние счётчики. В локальном хранилище браузера сохраняются только ключ авторизации и идентификатор выбранной семьи, необходимые для работы Сервиса.</p>

      <h2>9. Права субъекта персональных данных</h2>
      <p>9.1. Пользователь вправе получать сведения об обработке своих персональных данных (ст. 14 Закона), требовать их уточнения, блокирования или уничтожения, если данные являются неполными, устаревшими, неточными, незаконно полученными или не являются необходимыми для заявленной цели, отозвать согласие, обжаловать действия Оператора в Роскомнадзоре или в суде.</p>
      <p>9.2. Пользователь может самостоятельно изменить свои данные в Сервисе, выгрузить список лекарств и выписку о приёме лекарств (кнопка «Экспорт» в разделе «Аптечка») и удалить учётную запись (раздел «Семья» → «Удалить аккаунт»). Если в бесплатной версии Сервиса часть истории приёма скрыта из интерфейса, эти сведения не удаляются и по запросу Пользователя предоставляются ему бесплатно в полном объёме (ст. 14 Закона). Запрос также направляется на {OPERATOR.email}; он должен позволять идентифицировать Пользователя (адрес электронной почты учётной записи). Оператор отвечает в течение 10 рабочих дней с даты получения запроса; срок может быть продлён не более чем на 5 рабочих дней с направлением мотивированного уведомления (ч. 3 ст. 14, ч. 1 ст. 20 Закона).</p>
      <p>9.3. Доверенное лицо вправе в любой момент отказаться от получения писем или отписаться по ссылке в любом из них, получать сведения о своих данных и требовать их удаления письмом на {OPERATOR.email}; такое требование Оператор исполняет в срок, не превышающий 7 рабочих дней (ч. 3 ст. 21 Закона), а с момента отказа или отписки письма не направляются, а имя и адрес удаляются.</p>

      <h2>10. Несовершеннолетние</h2>
      <p>Самостоятельная регистрация в Сервисе допускается для лиц, достигших 18 лет. Сведения о несовершеннолетнем могут вноситься только его законным представителем (родителем, усыновителем, опекуном), имеющим на это полномочия, и обрабатываются после оформления требуемого законодательством согласия законного представителя (п. 4.3 Соглашения).</p>

      <h2>11. Заключительные положения</h2>
      <p>Оператор вправе изменять Политику. Новая редакция публикуется в Сервисе не менее чем за десять календарных дней до вступления в силу, если более короткий срок не требуется законом; при существенном изменении условий обработки Пользователю предлагается ознакомиться с новой редакцией и повторно дать согласие при входе в Сервис.</p>
    </Doc>
  )
}

